"""Leitor do e-mail da Ponte Câmbio: .eml com o relatório de operações em XLSX anexo.

Só lê e converte tipos. Não deduplica, não filtra e não calcula comissão.
"""

from __future__ import annotations

import io
import unicodedata
from email import policy
from email.message import EmailMessage
from email.parser import BytesParser
from pathlib import Path

import openpyxl
import pandas as pd

from tarvo.leitores.comum import cnpj14, data_br, dinheiro, num_br, pct

ABA = "Operações"
CABECALHO_REF = "Nº Operação"
RODAPE_TOTAL = "Total de operações"
RODAPE_SPREAD = "Spread total R$"

# Cabeçalho da planilha -> coluna do DataFrame. É o layout do arquivo da Ponte, não regra de negócio.
COLUNAS = {
    "Nº Operação": "ref_origem",
    "Data Contratação": "data_contratacao",
    "Data Liquidação": "data_liquidacao",
    "CNPJ Cliente": "cnpj",
    "Cliente": "cliente",
    "Moeda": "moeda",
    "Valor ME": "valor_me",
    "Taxa Cliente": "taxa_cliente",
    "PTAX Ref.": "ptax_ref",
    "Valor R$": "valor_brl",
    "Spread R$": "spread_brl",
    "Spread %": "spread_pct",
    "Spread Estimado R$ (D-1)": "spread_estimado_d1_brl",
    "IOF R$": "iof_brl",
    "Status Compliance": "status_compliance",
    "Observação": "observacao",
}

COLUNAS_SAIDA = ["arquivo_origem", "ref_origem", "linha_planilha", *(c for c in COLUNAS.values() if c != "ref_origem")]

DINHEIRO = ("valor_me", "valor_brl", "spread_brl", "spread_estimado_d1_brl", "iof_brl")
TAXAS = ("taxa_cliente", "ptax_ref")
DATAS = ("data_contratacao", "data_liquidacao")
TEXTOS = ("moeda", "status_compliance")


def _texto(v) -> str:
    """Texto de célula normalizado (NFC, sem espaços nas pontas) para comparar rótulos."""
    if v is None:
        return ""
    return unicodedata.normalize("NFC", str(v)).strip()


def _rotulo(v) -> str:
    """Rótulo de rodapé sem o ":" final."""
    return _texto(v).rstrip(":").strip()


def _vazia(linha: tuple) -> bool:
    return all(_texto(v) == "" for v in linha)


def _dinheiro_ou_none(v):
    n = num_br(v)
    return None if n is None else dinheiro(n)


def _anexo_xlsx(msg: EmailMessage, caminho: Path) -> tuple[str, bytes]:
    anexos = [p for p in msg.iter_attachments() if (p.get_filename() or "").lower().endswith(".xlsx")]
    if len(anexos) != 1:
        raise ValueError(f"{caminho.name}: esperado 1 anexo .xlsx, encontrados {len(anexos)}")
    return anexos[0].get_filename(), anexos[0].get_content()


def _corpo(msg: EmailMessage) -> str | None:
    parte = msg.get_body(preferencelist=("plain", "html"))
    return None if parte is None else parte.get_content()


def _linha_cabecalho(linhas: list[tuple]) -> tuple[int, dict[str, int]]:
    """Índice da linha que tem "Nº Operação" e mapa coluna_saida -> índice da célula."""
    for i, linha in enumerate(linhas):
        textos = [_texto(v) for v in linha]
        if CABECALHO_REF in textos:
            indices = {}
            for j, t in enumerate(textos):
                if t in COLUNAS:
                    indices[COLUNAS[t]] = j
            faltando = [h for h, c in COLUNAS.items() if c not in indices]
            if faltando:
                raise ValueError(f"cabeçalho sem as colunas: {', '.join(faltando)}")
            return i, indices
    raise ValueError(f"cabeçalho com '{CABECALHO_REF}' não encontrado na aba '{ABA}'")


def _valor_rodape(linha: tuple):
    """Primeira célula não vazia depois do rótulo."""
    for v in linha[1:]:
        if _texto(v) != "":
            return v
    return None


def _ler_rodape(linhas: list[tuple]) -> dict:
    rodape = {"total_operacoes_rodape": None, "spread_total_rodape": None}
    for linha in linhas:
        celulas = [v for v in linha if _texto(v) != ""]
        if not celulas:
            continue
        rotulo = _rotulo(celulas[0])
        if rotulo == RODAPE_TOTAL:
            n = num_br(celulas[1]) if len(celulas) > 1 else None
            if n is not None and n != n.to_integral_value():
                raise ValueError(f"'{RODAPE_TOTAL}' não é inteiro: {celulas[1]!r}")
            rodape["total_operacoes_rodape"] = None if n is None else int(n)
        elif rotulo == RODAPE_SPREAD:
            rodape["spread_total_rodape"] = _dinheiro_ou_none(celulas[1]) if len(celulas) > 1 else None
    return rodape


def _eh_rodape(linha: tuple) -> bool:
    celulas = [v for v in linha if _texto(v) != ""]
    return bool(celulas) and _rotulo(celulas[0]) in (RODAPE_TOTAL, RODAPE_SPREAD)


def _converter(bruto: dict, onde: str) -> dict:
    reg = dict(bruto)
    reg["ref_origem"] = _texto(bruto["ref_origem"])
    if not reg["ref_origem"]:
        raise ValueError(f"{onde}: '{CABECALHO_REF}' vazio")
    for c in DATAS:
        reg[c] = data_br(bruto[c])
    for c in DINHEIRO:
        reg[c] = _dinheiro_ou_none(bruto[c])
    for c in TAXAS:
        reg[c] = num_br(bruto[c])
    reg["spread_pct"] = pct(bruto["spread_pct"])
    reg["cnpj"] = cnpj14(bruto["cnpj"])
    if reg["cnpj"] is None:
        raise ValueError(f"{onde}: CNPJ inválido: {bruto['cnpj']!r}")
    reg["cliente"] = None if bruto["cliente"] is None else str(bruto["cliente"])
    for c in TEXTOS:
        reg[c] = _texto(bruto[c]) or None
    reg["observacao"] = _texto(bruto["observacao"]) or None
    return reg


def ler_ponte(caminho_eml) -> tuple[pd.DataFrame, dict]:
    """Lê o .eml da Ponte Câmbio. Devolve (operações, metadados do e-mail e do rodapé).

    Cada linha da aba "Operações" entre o cabeçalho e a primeira linha vazia vira uma linha do
    DataFrame, inclusive duplicatas e spreads negativos. O rodapé não é operação: vai para os metadados.
    """
    caminho = Path(caminho_eml)
    with open(caminho, "rb") as f:
        msg = BytesParser(policy=policy.default).parse(f)

    nome_anexo, conteudo = _anexo_xlsx(msg, caminho)
    arquivo_origem = f"{caminho.name}#{nome_anexo}"

    # Sem read_only: nele as linhas vazias podem sumir, e precisamos delas para parar e numerar.
    wb = openpyxl.load_workbook(io.BytesIO(conteudo), data_only=True)
    try:
        if ABA not in wb.sheetnames:
            raise ValueError(f"{arquivo_origem}: aba '{ABA}' não encontrada (abas: {wb.sheetnames})")
        linhas = [tuple(r) for r in wb[ABA].iter_rows(values_only=True)]
    finally:
        wb.close()

    i_cab, indices = _linha_cabecalho(linhas)

    registros = []
    i = i_cab + 1
    while i < len(linhas) and not _vazia(linhas[i]) and not _eh_rodape(linhas[i]):
        linha = linhas[i]
        linha_planilha = i + 1  # linhas do Excel começam em 1
        bruto = {c: (linha[j] if j < len(linha) else None) for c, j in indices.items()}
        reg = _converter(bruto, f"{arquivo_origem} linha {linha_planilha}")
        reg["arquivo_origem"] = arquivo_origem
        reg["linha_planilha"] = linha_planilha
        registros.append(reg)
        i += 1

    # dtype object: sem ele o pandas troca None por NaN nas colunas de texto.
    df = pd.DataFrame(registros, columns=COLUNAS_SAIDA, dtype=object)
    df["linha_planilha"] = df["linha_planilha"].astype("int64")

    data_hora = msg["Date"].datetime if msg["Date"] is not None else None
    metadados = {
        "arquivo_origem": arquivo_origem,
        "remetente": None if msg["From"] is None else str(msg["From"]),
        "data_email": None if data_hora is None else data_hora.date(),
        "data_hora_email": data_hora,
        "assunto": None if msg["Subject"] is None else str(msg["Subject"]),
        "corpo": _corpo(msg),
        **_ler_rodape(linhas[i:]),
    }
    return df, metadados
"""Leitor da planilha de taxas contratadas (XLSX mantido à mão pelo financeiro).

Só lê e converte tipos, sem regra de negócio: textos como "padrão", "INATIVO" ou "só remessa"
são preservados como vieram e interpretados depois.
"""

from __future__ import annotations

import re
from datetime import date, datetime
from pathlib import Path

import openpyxl
import pandas as pd

from tarvo.leitores.comum import cnpj14, data_br, pct, sem_acento

# Só esta aba. A aba histórica (2025) nunca é lida.
ABA = "Taxas vigentes"

# Cabeçalho da planilha (comparado sem acento e em maiúsculas) -> campo interno.
CABECALHOS = {
    "LOJISTA": "lojista",
    "CNPJ": "cnpj",
    "EC ORBE": "ec",
    "DEBITO": "taxa_debito",
    "CREDITO A VISTA": "taxa_credito_vista",
    "CRED. 2-6X": "taxa_parc_2_6",
    "CRED. 7-12X": "taxa_parc_7_12",
    "PIX": "taxa_pix",
    "ANTECIPACAO": "taxa_antecipacao",
    "SPREAD REMESSA": "spread",
    "VIGENCIA": "vigencia",
    "OBS": "obs",
}

CAMPOS_TAXA = ["taxa_debito", "taxa_credito_vista", "taxa_parc_2_6", "taxa_parc_7_12", "taxa_pix", "taxa_antecipacao"]

COLUNAS_SAIDA = [
    "arquivo_origem", "ref_origem", "lojista", "cnpj", "ec", *CAMPOS_TAXA,
    "spread_remessa_pct", "spread_remessa_texto", "vigencia_inicio", "vigencia_fim", "obs",
]

_DATA = r"(\d{2}/\d{2}/\d{4})"
_VIGENCIA_ATE = re.compile(rf"^ATE\s+{_DATA}$")
_VIGENCIA_A_PARTIR = re.compile(rf"^A PARTIR DE\s+{_DATA}$")
_VIGENCIA_DATA = re.compile(rf"^{_DATA}$")


def _vazio(v) -> bool:
    return v is None or (isinstance(v, str) and not v.strip())


def _vigencia(v) -> tuple[date | None, date | None]:
    """(início, fim). "até d" -> fim; "a partir de d" -> início; data simples -> início; vazio -> (None, None)."""
    if _vazio(v):
        return None, None
    if isinstance(v, (datetime, date)):
        return data_br(v), None
    texto = sem_acento(v)
    if m := _VIGENCIA_ATE.match(texto):
        return None, data_br(m.group(1))
    if m := _VIGENCIA_A_PARTIR.match(texto):
        return data_br(m.group(1)), None
    if m := _VIGENCIA_DATA.match(texto):
        return data_br(m.group(1)), None
    raise ValueError(f"vigência em formato desconhecido: {v!r}")


def _spread(v):
    """(pontos percentuais ou None, texto original ou None). Texto sem número ("padrão") fica só no texto."""
    if _vazio(v):
        return None, None
    if isinstance(v, str):
        return (pct(v) if v.strip().endswith("%") else None), v
    return pct(v), None


def _ec(v) -> str | None:
    if _vazio(v):
        return None
    if isinstance(v, float) and v.is_integer():
        v = int(v)
    return str(v).strip()


def _cnpj(v) -> str:
    c = cnpj14(v)
    if c is None:
        raise ValueError(f"CNPJ inválido: {v!r}")
    return c


def _localizar_cabecalho(ws) -> tuple[int, dict[str, int]]:
    """Linha do cabeçalho (a que tem a célula "Lojista") e coluna de cada campo."""
    for row in ws.iter_rows():
        if any(sem_acento(c.value) == "LOJISTA" for c in row if isinstance(c.value, str)):
            colunas = {}
            for c in row:
                if isinstance(c.value, str) and sem_acento(c.value) in CABECALHOS:
                    colunas[CABECALHOS[sem_acento(c.value)]] = c.column
            faltando = sorted(set(CABECALHOS.values()) - set(colunas))
            if faltando:
                raise ValueError(f"aba {ABA!r}, linha {row[0].row}: cabeçalhos ausentes: {faltando}")
            return row[0].row, colunas
    raise ValueError(f"aba {ABA!r}: célula 'Lojista' não encontrada")


def _converter(valores: dict, arquivo_origem: str, linha: int) -> dict:
    spread_pct, spread_texto = _spread(valores["spread"])
    inicio, fim = _vigencia(valores["vigencia"])
    return {
        "arquivo_origem": arquivo_origem,
        "ref_origem": f"linha {linha}",
        "lojista": valores["lojista"],
        "cnpj": _cnpj(valores["cnpj"]),
        "ec": _ec(valores["ec"]),
        **{campo: pct(valores[campo]) for campo in CAMPOS_TAXA},
        "spread_remessa_pct": spread_pct,
        "spread_remessa_texto": spread_texto,
        "vigencia_inicio": inicio,
        "vigencia_fim": fim,
        "obs": valores["obs"],
    }


def ler_taxas(caminho) -> pd.DataFrame:
    """Lê a aba "Taxas vigentes". ref_origem = "linha N" do Excel. Para na primeira linha sem lojista."""
    caminho = Path(caminho)
    wb = openpyxl.load_workbook(caminho, data_only=True)
    try:
        if ABA not in wb.sheetnames:
            raise ValueError(f"{caminho.name}: aba {ABA!r} não encontrada (abas: {wb.sheetnames})")
        ws = wb[ABA]
        linha_cab, colunas = _localizar_cabecalho(ws)
        registros = []
        for linha in range(linha_cab + 1, ws.max_row + 1):
            valores = {campo: ws.cell(row=linha, column=col).value for campo, col in colunas.items()}
            if _vazio(valores["lojista"]):
                break
            try:
                registros.append(_converter(valores, caminho.name, linha))
            except ValueError as e:
                raise ValueError(f"{caminho.name}, aba {ABA!r}, linha {linha}: {e}") from None
    finally:
        wb.close()
    # dtype=object: mantém Decimal, date e None (sem virar float/NaN)
    return pd.DataFrame(registros, columns=COLUNAS_SAIDA, dtype=object)
"""Conversões puras compartilhadas pelos leitores. Arquivo compartilhado: mude só com o time avisado."""

from __future__ import annotations

import re
import unicodedata
from datetime import date, datetime
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation

CENTAVO = Decimal("0.01")


def dinheiro(v: Decimal) -> Decimal:
    """Arredonda valor monetário para 2 casas, ROUND_HALF_UP."""
    return v.quantize(CENTAVO, rounding=ROUND_HALF_UP)


def num_br(s) -> Decimal | None:
    """Número em formato brasileiro ("1.234,56", "-389,00", "2,59%") ou int/float do Excel para Decimal.

    Vazio/None vira None. O "%" é só removido: "2,59%" vira Decimal("2.59").
    Não arredonda; para dinheiro, use dinheiro() em seguida.
    """
    if s is None:
        return None
    if isinstance(s, bool):
        raise TypeError(f"valor booleano não é número: {s!r}")
    if isinstance(s, Decimal):
        return s
    if isinstance(s, (int, float)):
        # via str: Decimal(0.1) traria o erro binário; Decimal(str(0.1)) == Decimal("0.1")
        return Decimal(str(s))
    texto = str(s).replace(" ", " ").strip()
    if texto.endswith("%"):
        texto = texto[:-1].strip()
    if not texto:
        return None
    texto = texto.replace(".", "").replace(",", ".")
    try:
        return Decimal(texto)
    except InvalidOperation:
        raise ValueError(f"número em formato brasileiro inválido: {s!r}") from None


def pct(v) -> Decimal | None:
    """Taxa da planilha para pontos percentuais.

    Número do Excel é fração (0.0259 vira Decimal("2.59")); texto precisa ter "%" ("2,59%" vira Decimal("2.59")).
    """
    if v is None:
        return None
    if isinstance(v, str):
        texto = v.strip()
        if not texto:
            return None
        if not texto.endswith("%"):
            raise ValueError(f"taxa em texto sem '%': {v!r}")
        return num_br(texto)
    fracao = num_br(v)
    if abs(fracao) > 1:
        raise ValueError(f"taxa numérica deveria ser fração (<= 1): {v!r}")
    return fracao * 100


def cnpj14(v) -> str | None:
    """CNPJ só com dígitos, completado com zeros à esquerda até 14. None se não houver 11 a 14 dígitos."""
    if v is None or isinstance(v, bool):
        return None
    if isinstance(v, float):
        if not v.is_integer():
            return None
        v = int(v)
    digitos = re.sub(r"\D", "", str(v))
    if not 11 <= len(digitos) <= 14:
        return None
    return digitos.zfill(14)


def data_br(s) -> date | None:
    """"dd/mm/aaaa" ou datetime/date do Excel para date. Vazio/None vira None."""
    if s is None:
        return None
    if isinstance(s, datetime):
        return s.date()
    if isinstance(s, date):
        return s
    texto = str(s).strip()
    if not texto:
        return None
    return datetime.strptime(texto, "%d/%m/%Y").date()


def sem_acento(s) -> str:
    """Maiúsculas, sem acentos, sem U+FFFD e com espaços colapsados.

    Só para exibição e evidência. NUNCA use como chave de casamento.
    """
    if s is None:
        return ""
    texto = unicodedata.normalize("NFKD", str(s).replace("�", ""))
    texto = "".join(c for c in texto if not unicodedata.combining(c))
    return " ".join(texto.upper().split())
# Padrões de nome (glob, sem diferenciar maiúsculas) para localizar cada arquivo de entrada.
# Nunca use o nome exato: os nomes mudam a cada competência.
arquivos:
  orbe: "*orbe*.csv"
  taxas: "*taxas*.xlsx"
  ponte_eml: "*.eml"
  plano_de_contas: "*plano_de_contas*.csv"
  aurora: "*aurora*.csv"
  meridiano: "*.ofx"
"""CLI do fechamento: python -m tarvo fechar --competencia AAAA-MM --entrada <dir> --saida <dir>."""

from __future__ import annotations

import argparse
import fnmatch
import sys
from pathlib import Path

import yaml

CONFIG_PADRAO = Path(__file__).resolve().parents[2] / "config" / "entradas.yaml"


class ErroEntrada(Exception):
    """Arquivo de entrada ausente ou ambíguo."""


def carregar_padroes(caminho_config: Path) -> dict[str, str]:
    with open(caminho_config, encoding="utf-8") as f:
        return yaml.safe_load(f)["arquivos"]


def localizar_arquivos(entrada: Path, padroes: dict[str, str]) -> dict[str, Path]:
    """Acha um arquivo por tipo usando o padrão de nome. Falha se faltar ou houver mais de um."""
    arquivos = sorted(p for p in entrada.iterdir() if p.is_file())
    encontrados: dict[str, Path] = {}
    problemas: list[str] = []
    for tipo, padrao in padroes.items():
        casados = [p for p in arquivos if fnmatch.fnmatch(p.name.lower(), padrao.lower())]
        if len(casados) == 1:
            encontrados[tipo] = casados[0]
        elif not casados:
            problemas.append(f"{tipo}: nenhum arquivo casa com '{padrao}'")
        else:
            nomes = ", ".join(p.name for p in casados)
            problemas.append(f"{tipo}: mais de um arquivo casa com '{padrao}': {nomes}")
    if problemas:
        raise ErroEntrada("\n".join(problemas))
    return encontrados


def cmd_fechar(args: argparse.Namespace) -> int:
    # import tardio: fechamento importa este módulo
    from tarvo.fechamento import ErroFechamento, fechar
    from tarvo.saida import ErroSaida

    entrada = Path(args.entrada)
    if not entrada.is_dir():
        print(f"Diretório de entrada não encontrado: {entrada}", file=sys.stderr)
        return 2
    try:
        resultado = fechar(entrada, Path(args.saida), args.competencia, config=Path(args.config))
    except ErroEntrada as e:
        print(f"Erro ao localizar arquivos de entrada:\n{e}", file=sys.stderr)
        return 2
    except (ErroSaida, ErroFechamento) as e:
        print(f"Erro na saída:\n{e}", file=sys.stderr)
        return 1
    except ValueError as e:
        print(f"Erro: {e}", file=sys.stderr)
        return 2

    print(f"Competência: {args.competencia}")
    print(f"Entrada: {entrada}")
    print(f"Saída: {args.saida}")
    print(f"Arquivos encontrados ({len(resultado.arquivos_entrada)}):")
    for tipo, caminho in resultado.arquivos_entrada.items():
        print(f"  {tipo}: {caminho.name}")
    print(f"Itens de saída: {resultado.itens}")
    print(f"Arquivos gravados ({len(resultado.arquivos_saida)}), validados sem problemas:")
    for nome in resultado.arquivos_saida:
        print(f"  {nome}")
    return 0


def construir_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="tarvo", description="Fechamento mensal da Tarvo Pagamentos")
    sub = parser.add_subparsers(dest="comando", required=True)

    fechar = sub.add_parser("fechar", help="Executa o fechamento de uma competência")
    fechar.add_argument("--competencia", required=True, help="AAAA-MM")
    fechar.add_argument("--entrada", required=True, help="Diretório com os arquivos de entrada")
    fechar.add_argument("--saida", required=True, help="Diretório de saída")
    fechar.add_argument("--config", default=str(CONFIG_PADRAO), help="YAML com os padrões de nome")
    fechar.set_defaults(func=cmd_fechar)
    return parser


def main(argv: list[str] | None = None) -> int:
    args = construir_parser().parse_args(argv)
    return args.func(args)


if __name__ == "__main__":
    raise SystemExit(main())

